<?php
/**
 * Server renderer for the site footer.
 *
 * One site-wide variant deliberately uses home-resolved URLs and retains the
 * attribute-driven “Say hello” entry: unlike the static comps, those links work
 * consistently from both the front page and inner WordPress routes.
 *
 * @var array<string, mixed> $attributes Block attributes.
 *
 * @package NextSaaS
 */

declare( strict_types=1 );
if ( ! defined( 'ABSPATH' ) ) { exit; }

$nextsaas_uid            = wp_unique_id( 'nextsaas-footer-' );
$nextsaas_columns        = nextsaas_items( $attributes, 'columns' );
$nextsaas_social_buttons = nextsaas_items( $attributes, 'socialButtons' );
$nextsaas_bottom_items   = nextsaas_items( $attributes, 'bottomItems' );
$nextsaas_action         = nextsaas_attr( $attributes, 'newsletterAction' );
$nextsaas_brand_url      = nextsaas_resolve_url( nextsaas_attr( $attributes, 'brandUrl', '@home' ) );
$nextsaas_brand_mode     = nextsaas_attr( $attributes, 'brandMode', 'text' );
$nextsaas_brand_media    = array(
	'mediaId'  => nextsaas_attr_int( $attributes, 'brandMediaId' ),
	'mediaUrl' => nextsaas_attr( $attributes, 'brandMediaUrl' ),
	'mediaAlt' => nextsaas_attr( $attributes, 'brandMediaAlt' ),
);
?>
<footer <?php echo nextsaas_section_attrs( 'site-footer', $attributes, array( 'pagefoot' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- escaped by core.?>>
	<div class="container"><div class="footer-top"><h3 data-nextsaas-rich="newsletterHeading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'newsletterHeading' ) ); ?></h3><div id="newsletter"><form id="<?php echo esc_attr( $nextsaas_uid ); ?>-newsletter-form"<?php if ( '' !== $nextsaas_action ) : ?> action="<?php echo esc_url( nextsaas_resolve_url( $nextsaas_action ) ); ?>"<?php endif; ?> method="post" data-nextsaas-newsletter="1" data-success-text="<?php echo esc_attr( nextsaas_attr( $attributes, 'newsletterSuccessText' ) ); ?>"><label class="newsletter-label" for="<?php echo esc_attr( $nextsaas_uid ); ?>-newsletter-email" data-nextsaas-rich="newsletterLabel"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'newsletterLabel' ) ); ?></label><div class="newsletter-field"><input type="email" id="<?php echo esc_attr( $nextsaas_uid ); ?>-newsletter-email" name="email" required placeholder="<?php echo esc_attr( nextsaas_attr( $attributes, 'newsletterPlaceholder' ) ); ?>" autocomplete="email" maxlength="254" aria-describedby="<?php echo esc_attr( $nextsaas_uid ); ?>-newsletter-note <?php echo esc_attr( $nextsaas_uid ); ?>-newsletter-status"><button type="submit" aria-label="<?php echo esc_attr( nextsaas_attr( $attributes, 'newsletterButtonLabel' ) ); ?>"><?php echo nextsaas_icon( 'arrow-up-right' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- trusted theme helper.?></button></div><p class="newsletter-note" id="<?php echo esc_attr( $nextsaas_uid ); ?>-newsletter-note" data-nextsaas-rich="newsletterNote"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'newsletterNote' ) ); ?></p><div class="newsletter-status" id="<?php echo esc_attr( $nextsaas_uid ); ?>-newsletter-status" role="status" aria-live="polite" aria-atomic="true"><?php echo esc_html( nextsaas_attr( $attributes, 'newsletterStatusText' ) ); ?></div></form></div></div><div class="footer-main"><div class="footer-about"><a href="<?php echo esc_url( $nextsaas_brand_url ); ?>" class="brand" aria-label="<?php echo esc_attr( nextsaas_attr( $attributes, 'brandAriaLabel' ) ); ?>"><?php if ( 'image' === $nextsaas_brand_mode ) : ?><?php echo nextsaas_media( $nextsaas_brand_media, 'brand-image' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- trusted theme helper.?><?php else : ?><span class="brand-mark" aria-hidden="true"><?php echo nextsaas_icon( 'asterisk' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- trusted theme helper.?></span><span data-nextsaas-rich="brandLabel"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'brandLabel' ) ); ?></span><?php endif; ?></a><p data-nextsaas-rich="aboutLineOne"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'aboutLineOne' ) ); ?></p><p data-nextsaas-rich="aboutLineTwo"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'aboutLineTwo' ) ); ?></p></div><?php foreach ( $nextsaas_columns as $nextsaas_column_index => $nextsaas_column ) : ?><div><h4 data-nextsaas-rich="columns.<?php echo esc_attr( (string) $nextsaas_column_index ); ?>.heading"><?php echo nextsaas_rich( isset( $nextsaas_column['heading'] ) ? (string) $nextsaas_column['heading'] : '' ); ?></h4><?php $nextsaas_links = isset( $nextsaas_column['links'] ) && is_array( $nextsaas_column['links'] ) ? $nextsaas_column['links'] : array(); foreach ( $nextsaas_links as $nextsaas_link_index => $nextsaas_link ) : $nextsaas_link_label = isset( $nextsaas_link['label'] ) ? (string) $nextsaas_link['label'] : ''; $nextsaas_link_element = isset( $nextsaas_link['element'] ) ? (string) $nextsaas_link['element'] : 'a'; ?><?php if ( 'button' === $nextsaas_link_element ) : ?><button type="button" data-info="terms" data-nextsaas-rich="columns.<?php echo esc_attr( (string) $nextsaas_column_index ); ?>.links.<?php echo esc_attr( (string) $nextsaas_link_index ); ?>.label"><?php echo nextsaas_rich( $nextsaas_link_label ); ?></button><?php else : ?><a href="<?php echo esc_url( nextsaas_resolve_url( isset( $nextsaas_link['url'] ) ? (string) $nextsaas_link['url'] : '' ) ); ?>" data-nextsaas-rich="columns.<?php echo esc_attr( (string) $nextsaas_column_index ); ?>.links.<?php echo esc_attr( (string) $nextsaas_link_index ); ?>.label"><?php echo nextsaas_rich( $nextsaas_link_label ); ?><?php if ( 0 === $nextsaas_link_index && in_array( $nextsaas_column_index, array( 0, 2 ), true ) ) : ?> <?php echo nextsaas_icon( 'arrow-up-right' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- trusted theme helper.?><?php elseif ( 2 === $nextsaas_column_index && count( $nextsaas_links ) - 1 === $nextsaas_link_index ) : ?> <?php echo nextsaas_icon( 'arrow-up' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- trusted theme helper.?><?php endif; ?></a><?php endif; ?><?php endforeach; ?></div><?php endforeach; ?></div><div class="footer-socials"><div><h4 data-nextsaas-rich="socialHeading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'socialHeading' ) ); ?></h4><p id="<?php echo esc_attr( $nextsaas_uid ); ?>-social-preview-note" data-nextsaas-rich="socialNote"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'socialNote' ) ); ?></p></div><nav class="footer-social-links" aria-label="<?php echo esc_attr( nextsaas_attr( $attributes, 'socialAriaLabel' ) ); ?>" aria-describedby="<?php echo esc_attr( $nextsaas_uid ); ?>-social-preview-note"><?php foreach ( $nextsaas_social_buttons as $nextsaas_social_index => $nextsaas_social ) : $nextsaas_social_label = isset( $nextsaas_social['label'] ) ? (string) $nextsaas_social['label'] : ''; ?><button type="button" data-social="<?php echo esc_attr( $nextsaas_social_label ); ?>" data-nextsaas-rich="socialButtons.<?php echo esc_attr( (string) $nextsaas_social_index ); ?>.label"><?php echo nextsaas_icon( isset( $nextsaas_social['icon'] ) ? (string) $nextsaas_social['icon'] : '' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- trusted theme helper.?><?php echo nextsaas_rich( $nextsaas_social_label ); ?></button><?php endforeach; ?></nav></div><div class="footer-wordmark" aria-hidden="true" data-nextsaas-rich="wordmark"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'wordmark' ) ); ?></div><div class="footer-bottom"><span data-nextsaas-rich="copyright"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'copyright' ) ); ?></span><div class="footer-legal"><?php foreach ( $nextsaas_bottom_items as $nextsaas_bottom_index => $nextsaas_item ) : $nextsaas_item_label = isset( $nextsaas_item['label'] ) ? (string) $nextsaas_item['label'] : ''; $nextsaas_item_element = isset( $nextsaas_item['element'] ) ? (string) $nextsaas_item['element'] : 'text'; ?><?php if ( 'button' === $nextsaas_item_element ) : ?><button type="button" data-info="<?php echo esc_attr( 0 === $nextsaas_bottom_index ? 'privacy' : 'terms' ); ?>" data-nextsaas-rich="bottomItems.<?php echo esc_attr( (string) $nextsaas_bottom_index ); ?>.label"><?php echo nextsaas_rich( $nextsaas_item_label ); ?></button><?php elseif ( 'a' === $nextsaas_item_element ) : ?><a href="<?php echo esc_url( nextsaas_resolve_url( isset( $nextsaas_item['href'] ) ? (string) $nextsaas_item['href'] : '' ) ); ?>" data-nextsaas-rich="bottomItems.<?php echo esc_attr( (string) $nextsaas_bottom_index ); ?>.label"><?php echo nextsaas_rich( $nextsaas_item_label ); ?></a><?php else : ?><span data-nextsaas-rich="bottomItems.<?php echo esc_attr( (string) $nextsaas_bottom_index ); ?>.label"><?php echo nextsaas_rich( $nextsaas_item_label ); ?></span><?php endif; ?><?php endforeach; ?></div></div></div>
	<dialog id="<?php echo esc_attr( $nextsaas_uid ); ?>-notice-dialog" aria-labelledby="<?php echo esc_attr( $nextsaas_uid ); ?>-notice-title" data-nextsaas-notice="1" data-social-title-suffix="<?php echo esc_attr( nextsaas_attr( $attributes, 'socialTitleSuffix' ) ); ?>" data-social-body="<?php echo esc_attr( nextsaas_attr( $attributes, 'socialDialogBody' ) ); ?>" data-privacy-title="<?php echo esc_attr( nextsaas_attr( $attributes, 'privacyDialogTitle' ) ); ?>" data-terms-title="<?php echo esc_attr( nextsaas_attr( $attributes, 'termsDialogTitle' ) ); ?>" data-legal-body="<?php echo esc_attr( nextsaas_attr( $attributes, 'legalDialogBody' ) ); ?>"><button type="button" class="dialog-close" aria-label="<?php echo esc_attr( nextsaas_attr( $attributes, 'dialogCloseLabel' ) ); ?>"><?php echo nextsaas_icon( 'plus' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- trusted theme helper.?></button><p class="eyebrow" data-nextsaas-rich="dialogEyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'dialogEyebrow' ) ); ?></p><h2 id="<?php echo esc_attr( $nextsaas_uid ); ?>-notice-title"></h2><p data-notice-body></p></dialog>
</footer>
